"""Compile the production Cinema controller, SPI master and codecs for host regression tests."""

import os
from pathlib import Path
import shutil
import subprocess
import tempfile


# AI: below section was generated by an AI
def find_compiler():
    """Use an available C++17 compiler, discovering MSVC's environment on Windows when needed."""
    for compiler in ("g++", "clang++", "cl"):
        if path := shutil.which(compiler):
            return path, os.environ.copy()
    if os.name == "nt":
        vswhere = Path(os.environ.get("ProgramFiles(x86)", "C:/Program Files (x86)")) / "Microsoft Visual Studio/Installer/vswhere.exe"
        if vswhere.exists():
            installations = subprocess.check_output([str(vswhere), "-all", "-products", "*", "-property", "installationPath"], text=True)
            for installation in installations.splitlines():
                setup = Path(installation) / "VC/Auxiliary/Build/vcvars64.bat"
                if not setup.exists():
                    continue
                output = subprocess.check_output(f'call "{setup}" >nul && set', shell=True, text=True)
                environment = dict(line.split("=", 1) for line in output.splitlines() if "=" in line and not line.startswith("="))
                path_value = next(value for key, value in environment.items() if key.upper() == "PATH")
                if compiler := shutil.which("cl", path=path_value):
                    return compiler, environment
    raise SystemExit("Install GCC, Clang, or Visual Studio C++ Build Tools to run Cinema tests.")


def main():
    """Keep build products and generated dependency shims in a temporary directory."""
    root = Path(__file__).resolve().parent.parent
    compiler, environment = find_compiler()
    msvc = Path(compiler).stem.lower() == "cl"
    with tempfile.TemporaryDirectory(prefix="wled-cinema-tests-") as directory:
        temporary = Path(directory)
        for header in ("wled.h", "Arduino.h", "freertos/FreeRTOS.h", "freertos/queue.h", "driver/gpio.h", "driver/spi_master.h", "driver/spi_slave.h", "esp_heap_caps.h", "esp_rom_gpio.h", "esp_system.h", "esp_timer.h", "soc/spi_periph.h"):
            destination = temporary / header
            destination.parent.mkdir(parents=True, exist_ok=True)
            contents = '#include "cinema_test_support.h"\n'
            if header == "wled.h":
                contents += f'#define private public\n#include "{(root / "wled00/cinema/cinema_controller.h").as_posix()}"\n#undef private\n'
            destination.write_text(contents, encoding="utf-8")
        config_source = (root / "wled00/cfg.cpp").read_text(encoding="utf-8")
        start = config_source.index("static bool deserializeCinemaConfig(")
        end = config_source.index("// AI: end", start)
        (temporary / "cinema_config_under_test.h").write_text(config_source[start:end], encoding="utf-8")
        unsupported = temporary / "unsupported.cpp"
        unsupported.write_text('#include "wled.h"\nint main(){ cinema::wled::CinemaController controller; cinema::wled::CinemaConfig config; config.generation=7; assert(controller.applyConfig(config)); controller.begin(); controller.service(millis()); assert(controller.config().generation==7 && !controller.transportReady()); }\n', encoding="utf-8")
        production = [root / "wled00/cinema/cinema_controller.cpp", root / "wled00/cinema/cinema_spi_master.cpp"]
        cases = {
            "protocol": [root / "tools/cinema_protocol_test.cpp"],
            "stream": [root / "tools/cinema_stream_test.cpp", root / "cinema-camera/src/spi_slave_endpoint.cpp", *production],
            "controller": [root / "tools/cinema_controller_test.cpp", *production],
            "config": [root / "tools/cinema_config_test.cpp", *production],
            "unsupported": [unsupported, *production],
        }
        for name, sources in cases.items():
            executable = temporary / (name + (".exe" if os.name == "nt" else ""))
            if msvc:
                flags = ["/nologo", "/EHsc", "/std:c++17", "/O2", f"/I{temporary}", f"/I{root / 'tools'}", f"/I{root / 'cinema-camera/include'}", f"/I{root / 'wled00/cinema'}", f"/Fe:{executable}"]
                if name != "unsupported":
                    flags += ["/DARDUINO_ARCH_ESP32", "/DCONFIG_IDF_TARGET_ESP32"]
            else:
                flags = ["-std=c++17", "-O2", "-pthread", f"-I{temporary}", f"-I{root / 'tools'}", f"-I{root / 'cinema-camera/include'}", f"-I{root / 'wled00/cinema'}", "-o", str(executable)]
                if name != "unsupported":
                    flags += ["-DARDUINO_ARCH_ESP32", "-DCONFIG_IDF_TARGET_ESP32"]
            subprocess.run([compiler, *flags, *map(str, sources)], cwd=temporary, env=environment, check=True)
            subprocess.run([str(executable)], cwd=temporary, env=environment, check=True)


if __name__ == "__main__":
    main()
# AI: end
